# update_camp_export.py
import zlib, base64, os, sys, glob

FILES = {'portal/views.py': '', 'templates/camp_dashboard.html': ''}

def apply_update():
    base = os.path.dirname(os.path.abspath(__file__))
    print(f"Deploying Camp Export updates into: {base}")
    for rel_path, b64_data in FILES.items():
        dest = os.path.join(base, rel_path.replace('/', os.sep))
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        raw_data = zlib.decompress(base64.b64decode(b64_data))
        with open(dest, "wb") as f:
            f.write(raw_data)
        print(f"Updated: {rel_path}")

    # Reload PythonAnywhere WSGI webapp
    wsgi_files = glob.glob('/var/www/*_wsgi.py')
    if wsgi_files:
        for wf in wsgi_files:
            try:
                os.utime(wf, None)
                print(f"Reloaded WSGI Web App: {wf}")
            except Exception as e:
                print(f"WSGI note: {e}")
    else:
        print("Note: If on PythonAnywhere, click 'Reload' in the Web tab!")

    print("\nCAMP EXPORT UPDATE COMPLETED SUCCESSFULLY!")

if __name__ == "__main__":
    apply_update()
